-- Local follow-up: the preceding migration was already applied while the
-- cross-application output contracts were finalized.
alter table public.technical_file_section_sources add column if not exists link_version integer not null default 1 check (link_version > 0);
update public.technical_file_section_sources set source_fingerprint=encode(extensions.digest(concat_ws('|',title,edition_or_revision,issuer,locator),'sha256'),'hex') where source_kind='manual_reference' and source_fingerprint is null;

create or replace function public.m7_evidence_link_json(p_organization_id uuid,p_product_id uuid,p_source_id uuid) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$ select jsonb_build_object('id',x.id,'sectionId',s.id,'sectionKey',s.section_key,'sourceKind',x.source_kind,'recordId',x.record_id,'linkVersion',x.link_version,'observedRevision',x.observed_revision,'sourceFingerprint',x.source_fingerprint,'availability',public.m7_evidence_section_source_state(p_organization_id,p_product_id,x.id),'staleAt',case when x.stale_at is null then null else to_char(x.stale_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') end,'staleReason',x.stale_reason,'currentObservedRevision',x.stale_current_revision,'currentFingerprint',x.stale_current_fingerprint,'reviewedAt',case when x.reviewed_at is null then null else to_char(x.reviewed_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') end,'createdAt',to_char(x.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')) from public.technical_file_section_sources x join public.technical_file_sections s on s.organization_id=x.organization_id and s.id=x.section_id where x.organization_id=p_organization_id and x.id=p_source_id $$;

create or replace function public.m7_evidence_readiness_json(p_organization_id uuid,p_product_id uuid) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$ with f as (select * from public.technical_files where organization_id=p_organization_id and product_id=p_product_id and status='active'),r as (select s.id,s.section_key,s.applicability,s.narrative,t.requires_narrative,t.requires_evidence,coalesce((select count(*) filter(where public.m7_evidence_section_source_state(p_organization_id,p_product_id,x.id)='current' and x.source_kind=any(t.allowed_source_kinds)) from public.technical_file_section_sources x where x.organization_id=s.organization_id and x.section_id=s.id),0)::int valid_count,coalesce((select count(*) filter(where public.m7_evidence_section_source_state(p_organization_id,p_product_id,x.id)='stale') from public.technical_file_section_sources x where x.organization_id=s.organization_id and x.section_id=s.id),0)::int stale_count,coalesce((select count(*) filter(where public.m7_evidence_section_source_state(p_organization_id,p_product_id,x.id)='unavailable') from public.technical_file_section_sources x where x.organization_id=s.organization_id and x.section_id=s.id),0)::int unavailable_count,coalesce((select array_agg(distinct x.stale_reason order by x.stale_reason) filter(where x.stale_reason is not null) from public.technical_file_section_sources x where x.organization_id=s.organization_id and x.section_id=s.id),array[]::text[]) reasons from public.technical_file_sections s join f on f.organization_id=s.organization_id and f.id=s.technical_file_id join public.technical_file_templates t on t.template_key=f.template_key and t.template_version=f.template_version and t.section_key=s.section_key),a as (select *,case when applicability='not_applicable' then 'complete' when stale_count>0 then 'stale' when (requires_narrative and narrative is null) and (requires_evidence and valid_count=0) then 'empty' when (requires_narrative and narrative is null) or (requires_evidence and valid_count=0) or unavailable_count>0 then 'partial' else 'complete' end status from r),g as (select section_key,code,priority,action_label from a cross join lateral(values('stale_evidence',1,'Review material source changes.'),('missing_narrative',2,'Add the required narrative.'),('missing_evidence',3,'Link valid evidence.'),('unavailable_evidence',4,'Replace unavailable evidence.'))v(code,priority,action_label) where(code='stale_evidence' and stale_count>0)or(code='missing_narrative' and applicability='applicable' and requires_narrative and narrative is null)or(code='missing_evidence' and applicability='applicable' and requires_evidence and valid_count=0)or(code='unavailable_evidence' and unavailable_count>0))select jsonb_build_object('technicalFileId',(select id from f),'overallStatus',case when exists(select 1 from a where status='stale')then'stale' when exists(select 1 from a where status in('empty','partial'))then case when not exists(select 1 from a where status='partial')then'empty' else'partial'end else'complete'end,'recalculationStatus','current','calculatedAt',to_char(clock_timestamp()at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'sections',coalesce((select jsonb_agg(jsonb_build_object('sectionKey',section_key,'status',status,'gapCount',(select count(*)from g where g.section_key=a.section_key),'validEvidenceCount',valid_count,'staleEvidenceCount',stale_count,'unavailableEvidenceCount',unavailable_count,'staleReasons',to_jsonb(reasons),'gaps',coalesce((select jsonb_agg(jsonb_build_object('sectionKey',g.section_key,'code',g.code,'priority',g.priority,'actionLabel',g.action_label)order by g.priority)from g where g.section_key=a.section_key),'[]'::jsonb))order by section_key)from a),'[]'::jsonb),'gaps',coalesce((select jsonb_agg(jsonb_build_object('sectionKey',section_key,'code',code,'priority',priority,'actionLabel',action_label)order by priority,section_key)from g),'[]'::jsonb)) $$;

drop function public.mark_technical_file_section_source_material_change_atomic(uuid,uuid,uuid,text,uuid,integer,text,text,text,uuid);
create function public.mark_technical_file_section_source_material_change_atomic(p_organization_id uuid,p_actor_user_id uuid,p_product_id uuid,p_section_key text,p_source_id uuid,p_expected_version integer,p_reason text,p_current_observed_revision text,p_current_fingerprint text,p_idempotency_key uuid) returns table(outcome text,result jsonb) language plpgsql security definer set search_path=public,pg_temp as $$ declare s public.technical_file_sections%rowtype;begin if p_reason not in('product_facts_changed','release_changed','support_basis_changed','risk_register_changed','sbom_revision_changed','source_validity_changed','source_quarantined','standard_edition_changed','document_version_changed')or char_length(btrim(coalesce(p_current_fingerprint,'')))not between 1 and 200 or not public.m7_technical_file_actor_can(p_organization_id,p_actor_user_id,'can_edit_technical_files')then return query select'invalid_request',null::jsonb;return;end if;select q.* into s from public.technical_file_sections q join public.technical_files f on f.organization_id=q.organization_id and f.id=q.technical_file_id where q.organization_id=p_organization_id and f.product_id=p_product_id and f.status='active'and q.section_key=p_section_key for update;if not found then return query select'not_found',null::jsonb;return;end if;if s.version<>p_expected_version then return query select'conflict',jsonb_build_object('currentVersion',s.version);return;end if;update public.technical_file_section_sources set stale_at=coalesce(stale_at,clock_timestamp()),stale_reason=p_reason,stale_current_revision=p_current_observed_revision,stale_current_fingerprint=p_current_fingerprint,link_version=link_version+1 where organization_id=p_organization_id and section_id=s.id and id=p_source_id;if not found then return query select'not_found',null::jsonb;return;end if;update public.technical_file_sections set version=version+1,updated_at=clock_timestamp(),updated_by=p_actor_user_id where organization_id=p_organization_id and id=s.id;insert into public.audit_logs(organization_id,user_id,action,entity_type,entity_id,changes)values(p_organization_id,p_actor_user_id,'technical_file.source_marked_stale','technical_file_section_source',p_source_id::text,jsonb_build_object('idempotencyKey',p_idempotency_key));return query select'marked_stale',jsonb_build_object('source',public.m7_evidence_link_json(p_organization_id,p_product_id,p_source_id));end $$;

revoke all on function public.m7_evidence_link_json(uuid,uuid,uuid),public.mark_technical_file_section_source_material_change_atomic(uuid,uuid,uuid,text,uuid,integer,text,text,text,uuid) from public,anon,authenticated;
alter function public.m7_evidence_link_json(uuid,uuid,uuid) owner to postgres; alter function public.mark_technical_file_section_source_material_change_atomic(uuid,uuid,uuid,text,uuid,integer,text,text,text,uuid) owner to postgres;
grant execute on function public.mark_technical_file_section_source_material_change_atomic(uuid,uuid,uuid,text,uuid,integer,text,text,text,uuid) to service_role;
notify pgrst, 'reload schema';
